sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Skip if no email to work with
    if (!current.employee_email) {
        return;
    }

    // Skip if employee reference is already set
    if (!current.employee.nil()) {
        return;
    }

    var email = current.employee_email.toString();

    // 1. Check if a sys_user with this email already exists
    var userGr = new GlideRecord('sys_user');
    userGr.addQuery('email', email);
    userGr.setLimit(1);
    userGr.query();

    if (userGr.next()) {
        // Found an existing user — link to them
        current.employee = userGr.sys_id;
        gs.info('Linked offboarding case to existing user: ' + userGr.user_name);
        return;
    }

    // 2. No match — create a new sys_user record
    var fullName = current.employee ? current.employee.toString() : '';
    var firstName = '';
    var lastName = '';

    if (fullName) {
        var parts = fullName.split(' ');
        firstName = parts[0];
        lastName = parts.slice(1).join(' '); // handles middle/last names
    }

    var newUser = new GlideRecord('sys_user');
    newUser.initialize();
    newUser.user_name = email.split('@')[0]; // e.g., "jadamczyk0" from "jadamczyk0@europa.eu"
    newUser.first_name = firstName;
    newUser.last_name = lastName;
    newUser.name = fullName;
    newUser.email = email;
    newUser.title = current.job_title ? current.job_title.toString() : '';
    newUser.employee_number = current.employee_id ? current.employee_id.toString() : '';
    newUser.active = false; // typically offboarded users are deactivated; flip to true if you want them active

    var newSysId = newUser.insert();

    if (newSysId) {
        current.employee = newSysId;
        gs.info('Created new sys_user "' + fullName + '" (' + newSysId + ') and linked to offboarding case.');
    } else {
        gs.warn('Failed to create sys_user for ' + fullName + ' / ' + email);
    }

})(current, previous);
